  const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const seed=()=>crypto.getRandomValues(new Uint32Array(1))[0],label=(side,type)=>(side==='buy'?'買 ':'賣 ')+(type==='call'?'Call':'Put');
  const strategyNames=Object.fromEntries(Object.entries(S).map(([id,s])=>[id,s.name])),strategyNotes=Object.fromEntries(Object.entries(S).map(([id,s])=>[id,s.structure]));
  const directionNotes={'buy-call':'支付權利金買入 Call。上漲通常有利，但仍可能因幅度不足或時間流逝而虧損。','sell-call':'賣出 Call 收權利金。大漲時需支付履約差額，沒有其他部位保護時，理論損失無上限。','buy-put':'支付權利金買入 Put。下跌通常有利，但跌幅不足時仍可能虧損。','sell-put':'賣出 Put 收權利金。上漲或未大跌通常有利，但大跌時可能虧損很多。'};
  let state=E.create(seed()),side='buy',type='call',followSpot=true,mode='single',intent='open',positionId=null,tab='holdings',chartMode='spot',toastTimer,practice=false,savedPractice=null,pendingImport=null,profile={},animations=true;
