    $('single-fields').hidden=isStrategy;$('strategy-fields').hidden=!isStrategy;$('execution-fields').hidden=isStrategy;$('limit-fields').hidden=kind==='market';$('time-in-force').disabled=kind==='market';$('limit-label').textContent=kind==='stop'?'停損觸發價':'限價';$('price-mid').hidden=kind==='stop';$('order-type').querySelector('[value="stop"]').disabled=!isClose;
