  if(document.modelContext?.registerTool){const lifecycle=new AbortController();const registrations=[{name:'read_simulation',title:'讀取虛擬帳戶',description:'Read this fictional European cash-settled options simulator, not real funds or live market.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>window.Lab.snapshot()},{name:'open_virtual_option',title:'開立虛擬期權委託',description:'Open a long or short Call or Put in virtual funds. Opposite direction opens new risk; close via close_virtual_position. Market IOC may partially fill; limit may remain working.',inputSchema:{type:'object',properties:{side:{type:'string',enum:['buy','sell']},type:{type:'string',enum:['call','put']},strike:{type:'number'},quantity:{type:'integer'},daysToExpiry:{type:'integer'},orderType:{type:'string',enum:['market','limit']},limit:{type:'number'},tif:{type:'string',enum:['DAY','GTC']}},required:['side','type','strike','quantity','daysToExpiry'],additionalProperties:false},execute:i=>window.Lab.openVirtual(i)},{name:'close_virtual_position',title:'平倉虛擬部位',description:'Close an existing virtual position by IOC, subject to quote depth and margin validation.',inputSchema:{type:'object',properties:{positionId:{type:'string'},quantity:{type:'integer'}},required:['positionId'],additionalProperties:false},execute:i=>window.Lab.closeVirtual(i.positionId,i.quantity)},{name:'advance_virtual_days',title:'推進虛擬交易日',description:'Advance 1 to 365 trading days, each with 6 simulated rounds. Settlement, orders and risk checks occur on the path.',inputSchema:{type:'object',properties:{days:{type:'integer',minimum:1,maximum:365}},required:['days'],additionalProperties:false},execute:i=>window.Lab.advanceVirtual(i.days)}];for(const tool of registrations){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}}addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
